function cancellationPolicyFor(job){const hoursUntil=(nextShiftDate(job)-Date.now())/3600000;return{adHoc:hoursUntil<=8,hoursUntil}}
function offerDeadlineLabel(j){const deadline=offerDeadline(j),left=Math.max(0,deadline-Date.now()),minutes=Math.floor(left/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60,remaining=days?`${days} d ${hours} godz.`:hours?`${hours} godz. ${mins} min`:`${Math.max(0,mins)} min`,date=new Intl.DateTimeFormat(currentLanguage==='en'?'en-GB':'pl-PL',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(deadline);return{deadline,date,remaining}}
function decorateOfferDeadlines(){document.querySelectorAll('.job-card').forEach(card=>{if(card.querySelector('.offer-deadline'))return;const j=jobs.find(x=>x.id===+card.dataset.id),meta=card.querySelector('.job-meta');if(!j||!meta)return;const d=offerDeadlineLabel(j);meta.insertAdjacentHTML('afterbegin',`<span class="offer-deadline">◷ Zgłoszenia: ${d.date}<small data-offer-deadline="${d.deadline.getTime()}">pozostało ${d.remaining}</small></span>`)})}
function decorateJobDeadline(id){const j=jobs.find(x=>x.id===id),details=jobModal.querySelector('.modal-details');if(!j||!details||details.querySelector('.deadline-detail'))return;const d=offerDeadlineLabel(j);details.insertAdjacentHTML('beforeend',`<div class="detail deadline-detail"><small>ZGŁOSZENIA DO</small><strong>${d.date}</strong><span data-offer-deadline="${d.deadline.getTime()}">Pozostało ${d.remaining}</span></div>`)}
function filteredJobs(){const q=document.querySelector('#searchInput').value.trim().toLowerCase();let list=jobs.filter(j=>j.active!==false&&!jobIsTaken(j)&&(activeDate==='all'||activeDate===j.day)&&(j.role+' '+j.company+' '+j.area+' '+(j.city||'')).toLowerCase().includes(q)&&j.rate>=filters.minRate&&(!filters.industries.length||filters.industries.includes(j.industry))&&timeMatches(j)&&(!filters.noExperience||!j.experience)&&(!filters.noEnglish||!j.english)&&(!filters.trainingProvided||j.trainingProvided)&&(!filters.lightWork||j.lightWork)&&(!filters.outfitProvided||j.outfitProvided)&&(!filters.sameDayPay||j.sameDayPay)&&(!filters.noQualifications||j.noQualifications));const sorters={nearest:(a,b)=>jobDistance(a)-jobDistance(b),rate:(a,b)=>b.rate-a.rate,newest:(a,b)=>b.newness-a.newness,recommended:(a,b)=>b.match-a.match};return list.sort((a,b)=>(Number(isJobPromoted(b))-Number(isJobPromoted(a)))||sorters[filters.sort](a,b))}
function requirementLabel(j){if(j.english)return 'Angielski wymagany';if(j.experience)return 'Doświadczenie wymagane';return 'Bez doświadczenia'}
function renderJobs(){const list=filteredJobs();document.querySelector('#resultCount').textContent=list.length;grid.innerHTML=list.length?list.map(j=>{const trip=estimateTravel(j),travel=locationFilterEnabled?`<span>⌖ ${jobDistance(j).toFixed(1).replace('.',',')} km</span><span class="travel-time">około ${trip.label}</span>`:'';return`<article class="job-card" data-id="${j.id}"><div class="job-cover" style="--cover:${j.color}"><div class="company-logo">${j.icon}</div><span class="match">${j.match}% DOPASOWANIA</span></div><div class="job-body"><h3>${j.role}</h3><span class="company">${j.company} · ${j.area}</span><div class="job-meta"><span>▣ ${j.date}, ${j.time}</span>${travel}<span class="requirement-tag">${requirementLabel(j)}</span></div><div class="job-footer"><div><strong>${j.rate*(j.end-j.start)} zł</strong><small> · ${j.rate} zł/h</small></div><button>${booked.includes(j.id)?'Zapisano ✓':'Zobacz'}</button></div></div></article>`}).join(''):'<div class="empty"><strong>Brak zmian spełniających kryteria</strong><br><br>Zmień grafik, zwiększ promień albo usuń część filtrów.</div>';document.querySelectorAll('.job-card').forEach(el=>{const job=jobs.find(item=>item.id===+el.dataset.id);el.classList.toggle('urgent',!!job&&nextShiftDate(job)-Date.now()<=86400000);el.dataset.urgentLabel=currentLanguage==='en'?'URGENT':'PILNE';el.onclick=()=>openJob(+el.dataset.id)});renderFilterSummary();renderBoardMap(list)}
let boardView='list',boardMap=null,boardMapLayer=null;
function initBoardMap(){if(boardMap||!window.L)return;boardMap=L.map('boardMap',{zoomControl:true}).setView([52.2297,21.0122],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(boardMap);boardMapLayer=L.layerGroup().addTo(boardMap)}
function renderBoardMap(list=filteredJobs()){if(boardView!=='map')return;initBoardMap();if(!boardMap)return;boardMapLayer.clearLayers();const points=[];list.forEach(job=>{if(!Number.isFinite(job.lat)||!Number.isFinite(job.lng))return;points.push([job.lat,job.lng]);const value=job.rate*(job.end-job.start);L.circleMarker([job.lat,job.lng],{radius:10,color:'#07152f',weight:3,fillColor:'#cfff47',fillOpacity:1}).bindPopup(`<div class="map-job-popup"><strong>${job.role}</strong><span>${job.company} · ${job.area}</span><small>${job.date}, ${job.time} · ${value} zł</small><button type="button" onclick="openJob(${job.id})">Zobacz ofertę →</button></div>`).addTo(boardMapLayer)});setTimeout(()=>{boardMap.invalidateSize();if(points.length===1)boardMap.setView(points[0],13);else if(points.length)boardMap.fitBounds(points,{padding:[35,35],maxZoom:13})},60)}
