function renderDashboardSummary(){const now=new Date(),dateText=new Intl.DateTimeFormat('pl-PL',{weekday:'long',day:'numeric',month:'long'}).format(now),isWorker=authUser?.role==='user',takenIds=new Set(applications.filter(a=>a.status==='confirmed').map(a=>a.jobId)),selected=confirmedJobIdsFor(authUser?.email).map(id=>jobs.find(j=>j.id===id)).filter(Boolean),unclaimed=jobs.filter(j=>j.active!==false&&!takenIds.has(j.id)),shown=isWorker?selected:unclaimed,value=shown.reduce((sum,j)=>sum+j.rate*(j.end-j.start),0),allActive=jobs.filter(j=>j.active!==false).length,count=shown.length;document.querySelector('#currentDate').textContent=dateText.charAt(0).toUpperCase()+dateText.slice(1);document.querySelector('#potentialLabel').textContent=isWorker?'Wartość moich potwierdzonych zmian':'Dostępne zmiany w tym tygodniu';document.querySelector('#potential').textContent=`${value.toLocaleString('pl-PL')} zł`;document.querySelector('#potentialMeta').textContent=isWorker?`${count} ${count===1?'potwierdzona zmiana':'potwierdzonych zmian'} w tym tygodniu`:`${count} ${count===1?'dostępna zmiana':'dostępnych zmian'} w tym tygodniu`;document.querySelector('#potentialBar').style.width=`${isWorker?Math.min(100,Math.round(count/5*100)):allActive?Math.round(count/allActive*100):0}%`}
