function processProfilePhoto(file,done){if(!file||!file.type.startsWith('image/'))return toast('Wybierz plik ze zdjęciem.');if(file.size>5*1024*1024)return toast('Zdjęcie może mieć maksymalnie 5 MB.');const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const size=Math.min(600,Math.max(img.width,img.height)),scale=size/Math.max(img.width,img.height),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);done(canvas.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(file)}
