function downloadWordFile(html,name){const documentHtml=`<!doctype html><html><head><meta charset="utf-8"><style>body{font:11pt Georgia,serif;line-height:1.5;margin:2cm}h1{text-align:center;font-size:18pt}h2{font-size:12pt;margin-top:18pt}.signatures{display:flex;justify-content:space-between;margin-top:70px}.muted{color:#667}</style></head><body>${html}</body></html>`,blob=new Blob(['\ufeff',documentHtml],{type:'application/msword'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.endsWith('.doc')?name:`${name}.doc`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadContractWord(){const paper=document.querySelector('#contractPreview .contract-paper'),job=jobs.find(j=>j.id===+document.querySelector('#contractDraftForm [name="jobId"]').value);if(!paper||!job)return;downloadWordFile(paper.innerHTML,`Temporeo_umowa_${job.role.replace(/[^a-z0-9ąćęłńóśźż]+/gi,'_')}.doc`)}
function supportDocumentHtml(type,job,app){const d=getJobDetails(job),today=new Intl.DateTimeFormat('pl-PL').format(new Date()),head=`<p class="muted">TEMPOREO · PROJEKT ROBOCZY · ${today}</p>`;if(type==='conditions')return`${head}<h1>Potwierdzenie warunków zlecenia</h1><p><b>Zlecenie:</b> ${job.role}</p><p><b>Strony:</b> ${job.company} / ${app.workerName}</p><p><b>Termin i miejsce:</b> ${job.date}, ${job.time}, ${d.address}</p><p><b>Stawka:</b> ${job.rate.toFixed(2).replace('.',',')} zł brutto/h</p><p><b>Zakres:</b></p><ul>${job.tasks.map(x=>`<li>${x}</li>`).join('')}</ul><p><b>Instrukcje:</b> ${d.arrival}; ${d.dressCode}; ${d.documents}; ${d.instructions}</p><div class="signatures"><span>________________ Pracodawca</span><span>________________ Pracownik</span></div>`;if(type==='hours')return`${head}<h1>Karta wykonania zlecenia i ewidencja godzin</h1><p><b>Zlecenie:</b> ${job.role} · ${app.workerName}</p><p><b>Planowany termin:</b> ${job.date}, ${job.time}</p><table border="1" cellspacing="0" cellpadding="8" width="100%"><tr><th>Data</th><th>Rozpoczęcie</th><th>Zakończenie</th><th>Przerwy</th><th>Liczba godzin</th></tr><tr><td>&nbsp;</td><td></td><td></td><td></td><td></td></tr></table><p>Uwagi: __________________________________________________________________</p><div class="signatures"><span>________________ Pracodawca</span><span>________________ Pracownik</span></div>`;if(type==='acceptance')return`${head}<h1>Protokół wykonania zlecenia</h1><p>Strony potwierdzają wykonanie zlecenia „${job.role}” przez ${app.workerName} w dniu ${job.date}.</p><p>Rezultat / uwagi: ____________________________________________________________</p><p>□ wykonano bez zastrzeżeń &nbsp; □ wykonano z uwagami &nbsp; □ zgłoszono rozbieżność</p><div class="signatures"><span>________________ Pracodawca</span><span>________________ Pracownik</span></div>`;return`${head}<h1>Formularz zgłoszenia rozbieżności</h1><p><b>Zlecenie:</b> ${job.role} · ${job.date}, ${job.time}</p><p><b>Osoba zgłaszająca:</b> __________________________</p><p><b>Rodzaj problemu:</b> □ brak obecności □ inne warunki □ czas pracy □ bezpieczeństwo □ inne</p><p><b>Opis:</b></p><p style="height:180px;border:1px solid #999"></p><p><b>Załączniki / dowody:</b> _________________________________________________</p><p>Data i podpis: ____________________________________________________________</p>`}
function downloadSupportDocument(type){const job=jobs.find(j=>j.id===+document.querySelector('#contractDraftForm [name="jobId"]').value),app=job&&confirmedApplicationFor(job.id);if(!job||!app)return;const names={conditions:'potwierdzenie_warunkow',hours:'ewidencja_godzin',acceptance:'protokol_wykonania',issue:'zgloszenie_rozbieznosci'};downloadWordFile(supportDocumentHtml(type,job,app),`Temporeo_${names[type]}_${job.id}.doc`)}
function setupContractDraftWorkflow(){const modal=document.createElement('dialog');modal.id='contractDraftModal';modal.className='contract-draft-modal';modal.innerHTML=`<button class="modal-close" aria-label="Zamknij">×</button><div class="contract-draft-head"><div><p class="eyebrow">DOKUMENT PO MATCHU</p><h2>Projekt umowy dla zlecenia</h2><p id="contractDraftMatch"></p></div><span>Wersja robocza</span></div><div class="contract-warning"><strong>To pomocniczy wzór, a nie automatyczna porada prawna.</strong><p>Pracodawca odpowiada za wybór właściwego rodzaju umowy. Jeśli praca ma cechy stosunku pracy, trzeba zastosować właściwą umowę pracowniczą. Przed użyciem komercyjnym wzór powinien zatwierdzić prawnik.</p><div class="document-pack"><small>PAKIET DOKUMENTÓW WORD</small><button type="button" data-support-doc="conditions">Warunki zlecenia</button><button type="button" data-support-doc="hours">Ewidencja godzin</button><button type="button" data-support-doc="acceptance">Protokół wykonania</button><button type="button" data-support-doc="issue">Zgłoszenie rozbieżności</button></div></div><div class="contract-workspace"><form id="contractDraftForm" class="contract-fields"><input type="hidden" name="jobId"><h3>Dane do uzupełnienia</h3><label>Zleceniodawca / pełna nazwa<input name="employerName" required></label><div class="field-row"><label>NIP<input name="employerNip" inputmode="numeric"></label><label>Osoba reprezentująca<input name="employerRepresentative"></label></div><label>Adres firmy<input name="employerAddress" placeholder="Adres siedziby"></label><label>Zleceniobiorca<input name="workerName" required></label><label>Adres zleceniobiorcy<input name="workerAddress" placeholder="Uzupełnij z pracownikiem offline"></label><label>Identyfikator do rozliczeń<input name="workerIdentifier" placeholder="Uzupełnij offline, nie zapisuj bez potrzeby"></label><label>Miejsce wykonania<input name="place"></label><label>Potwierdzanie godzin<input name="hoursMethod"></label><label>Termin zapłaty<input name="paymentDate"></label><label>Dodatkowe ustalenia<textarea name="extra" rows="3" placeholder="Np. zasady przekazania sprzętu"></textarea></label><button type="submit" class="secondary contract-save">Zapisz i odśwież projekt</button></form><div id="contractPreview" class="contract-preview"></div></div><div class="contract-footer"><p>Stawka jest ustalana indywidualnie i przenoszona z zaakceptowanej oferty. Przed użyciem dokumentów skonsultuj ich treść z prawnikiem.</p><div><button type="button" class="contract-close">Zamknij</button><button type="button" class="contract-word">Pobierz Word</button><button type="button" class="primary contract-print">Drukuj / PDF</button></div></div>`;document.body.appendChild(modal);modal.querySelectorAll('.modal-close,.contract-close').forEach(button=>button.onclick=()=>modal.close());modal.querySelector('form').onsubmit=e=>{e.preventDefault();saveContractDraft(e.target)};modal.querySelectorAll('input,textarea').forEach(input=>input.oninput=()=>renderContractPreview(modal.querySelector('[name="jobId"]').value));modal.querySelector('.contract-print').onclick=printContractDraft;modal.querySelector('.contract-word').onclick=downloadContractWord;modal.querySelectorAll('[data-support-doc]').forEach(button=>button.onclick=()=>downloadSupportDocument(button.dataset.supportDoc))}
