function candidateProfile(email,name){const known={'lukasz@example.pl':{attendance:98,cancellations:1,city:'Warszawa',skills:['Logistyka','Obsługa wydarzeń','Punktualność']},'maria@example.pl':{attendance:96,cancellations:2,city:'Warszawa',skills:['Obsługa klienta','Rejestracja gości','Eventy']},'jan@example.pl':{attendance:94,cancellations:1,city:'Warszawa',skills:['Logistyka','Pakowanie','Praca zespołowa']}},base=known[email]||{attendance:97,cancellations:0,city:userProfile.city||'Warszawa',skills:userProfile.skills?.length?userProfile.skills:['Dyspozycyjność','Punktualność']},workerReviews=reviews.filter(r=>r.workerEmail===email),rating=workerReviews.length?Math.round(workerReviews.reduce((sum,r)=>sum+r.score,0)/workerReviews.length*10)/10:null;return{...base,rating,completed:workerReviews.length,reviews:workerReviews}}
