function setupApplicationWorkflow(){const notifications=document.createElement('div');notifications.id='workerNotifications';notifications.className='worker-notifications';notifications.hidden=true;document.querySelector('#discover .hero').after(notifications);const modal=document.createElement('dialog');modal.id='candidatesModal';modal.className='candidates-modal';modal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidatesContent"></div>';document.body.appendChild(modal);modal.querySelector('.modal-close').onclick=()=>modal.close();const profileModal=document.createElement('dialog');profileModal.id='candidateProfileModal';profileModal.className='candidate-profile-modal';profileModal.innerHTML='<button class="modal-close" aria-label="Zamknij">×</button><div id="candidateProfileContent"></div>';document.body.appendChild(profileModal);profileModal.querySelector('.modal-close').onclick=()=>profileModal.close();setInterval(()=>{if(expireApplications()){renderWorkerNotifications();renderAdminJobs()}document.querySelectorAll('[data-deadline]').forEach(el=>el.textContent=remainingTime(+el.dataset.deadline));document.querySelectorAll('[data-offer-deadline]').forEach(el=>{const left=Math.max(0,+el.dataset.offerDeadline-Date.now()),minutes=Math.floor(left/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60;el.textContent=`${el.closest('.offer-deadline')?'pozostało ':'Pozostało '}${days?`${days} d ${hours} godz.`:hours?`${hours} godz. ${mins} min`:`${Math.max(0,mins)} min`}`})},1000)}
