function translateString(value){if(currentLanguage!=='en')return value;const leading=value.match(/^\s*/)?.[0]||'',trailing=value.match(/\s*$/)?.[0]||'',core=value.trim();let translated=EN[core]||core;if(translated===core){Object.keys(EN).filter(key=>key.length>=4&&core.includes(key)).sort((a,b)=>b.length-a.length).forEach(key=>{const escaped=key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),pattern=new RegExp(`(?<![\\p{L}\\p{N}])${escaped}(?![\\p{L}\\p{N}])`,'gu');translated=translated.replace(pattern,EN[key])})}EN_PATTERNS.forEach(([pattern,replacement])=>translated=translated.replace(pattern,replacement));return leading+translated+trailing}
function translateNode(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(!node.nodeValue.trim())continue;if(!originalText.has(node))originalText.set(node,node.nodeValue);const source=originalText.get(node);node.nodeValue=currentLanguage==='en'?translateString(source):source}root.querySelectorAll?.('[placeholder],[title],[aria-label]').forEach(el=>{if(!originalAttributes.has(el))originalAttributes.set(el,{});const saved=originalAttributes.get(el);['placeholder','title','aria-label'].forEach(attr=>{if(!el.hasAttribute(attr))return;if(!(attr in saved))saved[attr]=el.getAttribute(attr);el.setAttribute(attr,currentLanguage==='en'?translateString(saved[attr]):saved[attr])})})}
Object.assign(EN,{'Opcja „Bez doświadczenia” jest niedostępna, ponieważ wybrano co najmniej jedną umiejętność.':'The “No experience” option is unavailable because at least one skill has been selected.'});function setLanguage(language){currentLanguage=language;localStorage.setItem('flexo-language',language);document.documentElement.lang=language;document.title=language==='en'?'Temporeo — work when you want':'Temporeo — praca, kiedy chcesz';document.querySelectorAll('.language-switch button').forEach(button=>button.classList.toggle('active',button.dataset.lang===language));renderProfile();renderJobs();renderBooked();renderAdminJobs();renderWorkerNotifications();renderAuthState();if(jobsMap)updateMap();translateNode(document.body)}
function setupLanguageSelector(){const switcher=document.createElement('div');switcher.className='language-switch';switcher.setAttribute('aria-label','Wybór języka');switcher.innerHTML='<span class="language-label">🌐 <b>Język</b></span><button data-lang="pl" title="Polski">PL</button><button data-lang="en" title="English">EN</button>';document.body.appendChild(switcher);switcher.querySelectorAll('button').forEach(button=>button.onclick=()=>setLanguage(button.dataset.lang));new MutationObserver(records=>{if(currentLanguage!=='en')return;records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE){if(node.nodeValue.trim()){if(!originalText.has(node))originalText.set(node,node.nodeValue);node.nodeValue=translateString(originalText.get(node))}}else if(node.nodeType===Node.ELEMENT_NODE)translateNode(node)}))}).observe(document.body,{childList:true,subtree:true});setLanguage(currentLanguage)}
