function currentTourRole(){return authUser?.role||'guest'}
function clearOnboardingHighlight(){onboardingTarget?.classList.remove('tour-highlight');onboardingTarget=null}
function closeOnboarding(completed=false){clearOnboardingHighlight();document.querySelector('#onboardingLayer')?.remove();if(completed)localStorage.setItem(`flexo-onboarding-v2-${onboardingRole}`,'done')}
function positionOnboarding(target,card){const rect=target.getBoundingClientRect(),gap=14,width=Math.min(370,innerWidth-24);card.style.width=`${width}px`;const cardHeight=card.offsetHeight||260;let left=Math.max(12,Math.min(innerWidth-width-12,rect.left+rect.width/2-width/2)),top=rect.bottom+gap;if(top+cardHeight>innerHeight-12)top=Math.max(12,rect.top-cardHeight-gap);if(innerWidth<=700){left=12;top=rect.bottom+gap;if(top+cardHeight>innerHeight-82)top=Math.max(12,rect.top-cardHeight-gap)}card.style.left=`${left}px`;card.style.top=`${top}px`}
function renderOnboardingStep(){clearOnboardingHighlight();const step=onboardingSteps[onboardingIndex],layer=document.querySelector('#onboardingLayer');if(!step||!layer)return closeOnboarding(true);const target=visibleElement(step.selector);if(!target){onboardingIndex++;return renderOnboardingStep()}target.scrollIntoView({behavior:'smooth',block:'center'});onboardingTarget=target;target.classList.add('tour-highlight');const card=layer.querySelector('.tour-card');card.innerHTML=`<div class="tour-progress"><span>${onboardingIndex+1} / ${onboardingSteps.length}</span><button type="button" data-tour-skip>Pomiń</button></div><h3>${step.title}</h3><p>${step.text}</p><div class="tour-actions"><button type="button" data-tour-back ${onboardingIndex===0?'disabled':''}>Wstecz</button><button type="button" class="tour-next">${onboardingIndex===onboardingSteps.length-1?'Gotowe':'Dalej'}</button></div>`;if(currentLanguage==='en')translateNode(card);card.querySelector('[data-tour-skip]').onclick=()=>closeOnboarding(true);card.querySelector('[data-tour-back]').onclick=()=>{onboardingIndex--;renderOnboardingStep()};card.querySelector('.tour-next').onclick=()=>{if(onboardingIndex===onboardingSteps.length-1)closeOnboarding(true);else{onboardingIndex++;renderOnboardingStep()}};setTimeout(()=>positionOnboarding(target,card),320)}
function startOnboarding(force=false){closeOnboarding();onboardingRole=currentTourRole();if(!force&&localStorage.getItem(`flexo-onboarding-v2-${onboardingRole}`))return;const copy=onboardingCopy();onboardingSteps=[...copy.common,...copy[onboardingRole]];onboardingIndex=0;const layer=document.createElement('div');layer.id='onboardingLayer';layer.className='tour-layer';layer.innerHTML='<div class="tour-shade"></div><section class="tour-card" role="dialog" aria-live="polite"></section>';document.body.appendChild(layer);renderOnboardingStep()}
function setupOnboarding(){const help=document.createElement('button');help.id='onboardingHelp';help.className='onboarding-help';help.innerHTML='<span>?</span><b>Instrukcja</b>';help.onclick=()=>startOnboarding(true);document.body.appendChild(help);addEventListener('resize',()=>{const card=document.querySelector('.tour-card');if(card&&onboardingTarget)positionOnboarding(onboardingTarget,card)});addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#onboardingLayer'))closeOnboarding(true)});setTimeout(()=>startOnboarding(false),900)}
const finishAuthBeforeOnboarding=finishAuth;finishAuth=function(user){finishAuthBeforeOnboarding(user);setTimeout(()=>startOnboarding(false),500)};
setupOnboarding();
function decorateTeamJobs(){document.querySelectorAll('.admin-job-row').forEach(row=>{const action=row.querySelector('.candidates-action'),id=+(action?.getAttribute('onclick')?.match(/\((\d+)\)/)?.[1]||0),job=jobs.find(j=>j.id===id);if(!job)return;const filled=filledPositions(id),status=row.querySelector(':scope > .status'),info=row.querySelector('div:nth-child(2)>small'),finished=teamReviewState(id).done||job.completed;if(info&&job.positions>1&&!info.querySelector?.('.team-inline'))info.insertAdjacentHTML('beforeend',` <b class="team-inline">· Zespół ${filled}/${job.positions}</b>`);if(status&&job.positions>1&&job.active!==false&&!job.cancelledByEmployer&&!finished){status.className=`status ${filled>=job.positions?'accepted':filled?'partial':'available'}`;status.textContent=filled>=job.positions?`Komplet ${filled}/${job.positions}`:filled?`Obsadzono ${filled}/${job.positions}`:`Wolne ${job.positions} miejsc`}})}
function updateTeamAdminStats(){const active=jobs.filter(j=>j.active!==false),filled=active.reduce((sum,j)=>sum+Math.min(j.positions||1,filledPositions(j.id)),0),places=active.reduce((sum,j)=>sum+(j.positions||1),0),value=active.reduce((sum,j)=>sum+jobBilling(j).value,0),unfilledValue=active.reduce((sum,j)=>sum+jobBilling(j).unitValue*openPositions(j),0),commission=Math.round(value*TEMPOREO_COMMISSION_RATE),potential=Math.round(unfilledValue*TEMPOREO_COMMISSION_RATE);document.querySelector('#adminJobsValue').textContent=`${value.toLocaleString('pl-PL')} zł`;document.querySelector('#adminActiveCommission').textContent=`${commission.toLocaleString('pl-PL')} zł`;document.querySelector('#adminInactiveValue').textContent=`${unfilledValue.toLocaleString('pl-PL')} zł`;document.querySelector('#adminUnclaimedCommission').textContent=`${potential.toLocaleString('pl-PL')} zł`;document.querySelector('#adminActiveShare').textContent=`${places?Math.round(filled/places*100):0}%`;document.querySelector('#adminFillStatus').textContent=`${filled} z ${places} miejsc obsadzonych`;if(authUser?.role==='employer'){const mine=jobs.filter(j=>j.ownerEmail===authUser.email),mineFilled=mine.reduce((sum,j)=>sum+filledPositions(j.id),0);document.querySelector('#employerFilled').textContent=mineFilled}}
